using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Xml;

namespace CadUrdfMaker.Core
{
    public static class MeshIO
    {
        public static void WriteStl(string path,IList<double> triangles)
        {
            if(triangles.Count==0||triangles.Count%9!=0)throw new InvalidDataException("Mesh requires complete triangles.");
            using(var stream=File.Create(path))using(var w=new BinaryWriter(stream)){
                var header=new byte[80];Encoding.ASCII.GetBytes("CAD-URDF Maker | vertices in metres").CopyTo(header,0);w.Write(header);w.Write((uint)(triangles.Count/9));
                for(int i=0;i<triangles.Count;i+=9){var a=new[]{triangles[i],triangles[i+1],triangles[i+2]};var b=new[]{triangles[i+3],triangles[i+4],triangles[i+5]};var c=new[]{triangles[i+6],triangles[i+7],triangles[i+8]};var n=Math3.Cross(Math3.Sub(b,a),Math3.Sub(c,a));double len=Math.Sqrt(Math3.Dot(n,n));for(int k=0;k<3;k++)w.Write((float)(len>1e-20?n[k]/len:0));for(int k=0;k<9;k++){float v=(float)triangles[i+k];if(float.IsNaN(v)||float.IsInfinity(v))throw new InvalidDataException("Invalid mesh coordinate.");w.Write(v);}w.Write((ushort)0);}
            }
        }
        public static double[] ReadStl(string path)
        {
            using(var s=File.OpenRead(path))using(var r=new BinaryReader(s)){if(s.Length<84)throw new InvalidDataException("Invalid binary STL.");s.Position=80;uint n=r.ReadUInt32();if(s.Length!=84L+50L*n||n>10000000)throw new InvalidDataException("Only bounded binary STL is supported.");var v=new double[checked((int)n*9)];for(int i=0;i<v.Length;i+=9){s.Position+=12;for(int k=0;k<9;k++)v[i+k]=r.ReadSingle();s.Position+=2;}return v;}
        }
        public static double[] Transform(IList<double> v,double[] t) { var result=new double[v.Count];for(int i=0;i<v.Count;i+=3){var p=Math3.Point(t,new[]{v[i],v[i+1],v[i+2]});Array.Copy(p,0,result,i,3);}return result; }
    }
    public static class UrdfExport
    {
        static string F(double x) { return x.ToString("G17",CultureInfo.InvariantCulture); }
        static string V(double[] x) { return string.Join(" ",x.Select(F)); }
        public static string FileName(RobotProject p) { string error=Validation.RobotNameError(p.Name);if(error!=null)throw new InvalidDataException(error);return p.Name+".urdf"; }
        static void Element(XmlWriter w,string name,params string[] pairs){w.WriteStartElement(name);for(int i=0;i<pairs.Length;i+=2)w.WriteAttributeString(pairs[i],pairs[i+1]);w.WriteEndElement();}
        public static void WriteUrdf(string path,RobotProject p)
        {
            var errors=Validation.Check(p);if(errors.Any(x=>x.Severity=="error"))throw new InvalidDataException(string.Join("\n",errors.Select(x=>x.Target+": "+x.Message)));
            using(var w=XmlWriter.Create(path,new XmlWriterSettings{Indent=true,IndentChars="  ",Encoding=new UTF8Encoding(false),NewLineChars="\n"})){
                w.WriteStartDocument();w.WriteComment(" Generated by CAD-URDF Maker. SI units. Inertia about each link CoG in link axes. ");w.WriteStartElement("robot");w.WriteAttributeString("name",p.Name);
                foreach(var l in p.Links.OrderBy(x=>x.Name,StringComparer.Ordinal)){
                    var physics=OriginWorkflow.Properties(p,l);w.WriteStartElement("link");w.WriteAttributeString("name",l.Name);w.WriteStartElement("inertial");Element(w,"origin","xyz",V(physics.Cog),"rpy","0 0 0");Element(w,"mass","value",F(physics.Mass));var m=physics.Inertia;Element(w,"inertia","ixx",F(m[0]),"ixy",F(m[1]),"ixz",F(m[2]),"iyy",F(m[4]),"iyz",F(m[5]),"izz",F(m[8]));w.WriteEndElement();
                    foreach(string kind in new[]{"visual","collision"}){w.WriteStartElement(kind);Element(w,"origin","xyz","0 0 0","rpy","0 0 0");w.WriteStartElement("geometry");Element(w,"mesh","filename","meshes/"+l.Name+".stl");w.WriteEndElement();if(kind=="visual"){w.WriteStartElement("material");w.WriteAttributeString("name","cad_urdf_material");Element(w,"color","rgba","0.72 0.79 0.84 1");w.WriteEndElement();}w.WriteEndElement();}w.WriteEndElement();
                }
                foreach(var j in p.Joints.OrderBy(x=>x.Name,StringComparer.Ordinal)){
                    var parent=p.Links.Single(l=>l.Id==j.Parent);var child=p.Links.Single(l=>l.Id==j.Child);var t=Math3.Multiply(Math3.Inverse(Math3.LinkFrame(p,parent)),Math3.LinkFrame(p,child));
                    w.WriteStartElement("joint");w.WriteAttributeString("name",j.Name);w.WriteAttributeString("type",j.Type);Element(w,"parent","link",parent.Name);Element(w,"child","link",child.Name);Element(w,"origin","xyz",V(new[]{t[3],t[7],t[11]}),"rpy",V(p.ChildFramesFollowRoot?new double[3]:Math3.Rpy(t)));
                    if(j.Type!="fixed"){Element(w,"axis","xyz",V(Math3.JointAxis(p,j)));if(j.Type=="continuous")Element(w,"limit","effort",F(j.Effort),"velocity",F(j.Velocity));else Element(w,"limit","lower",F(j.Lower),"upper",F(j.Upper),"effort",F(j.Effort),"velocity",F(j.Velocity));}w.WriteEndElement();
                }
                w.WriteEndElement();w.WriteEndDocument();
            }
        }
        public static void Package(string destination,RobotProject p,IDictionary<string,double[]> componentMeshes)
        {
            var errors=Validation.Check(p);if(errors.Count!=0)throw new InvalidDataException(string.Join("\n",errors.Select(x=>x.Target+": "+x.Message)));
            string full=Path.GetFullPath(destination);string parent=Path.GetDirectoryName(full);if(string.IsNullOrEmpty(parent)||full==Path.GetPathRoot(full))throw new ArgumentException("Choose a dedicated output folder.");
            // Replace only folders created by this application, never arbitrary directories.
            if(Directory.Exists(full)&&!File.Exists(Path.Combine(full,".cad-urdf-maker-output")))throw new IOException("Existing destination is not a CAD-URDF Maker export. Choose a new folder.");
            Directory.CreateDirectory(parent);string stage=Path.Combine(parent,".cad-urdf-stage-"+Guid.NewGuid().ToString("N"));string backup=full+".previous-"+Guid.NewGuid().ToString("N");Directory.CreateDirectory(stage);
            try {
                string urdfFile=FileName(p);Directory.CreateDirectory(Path.Combine(stage,"meshes"));WriteUrdf(Path.Combine(stage,urdfFile),p);
                foreach(var l in p.Links){var triangles=new List<double>();foreach(string id in l.Components){double[] mesh;if(!componentMeshes.TryGetValue(id,out mesh)||mesh.Length==0)throw new InvalidDataException("Missing mesh for component "+id);var component=p.Components.Single(c=>c.Id==id);triangles.AddRange(MeshIO.Transform(mesh,Math3.Multiply(Math3.Inverse(Math3.LinkFrame(p,l)),component.ZeroTransform)));}MeshIO.WriteStl(Path.Combine(stage,"meshes",l.Name+".stl"),triangles);}
                var report=new { Application="CAD-URDF Maker",RobotName=p.Name,UrdfFile=urdfFile,Units=new{Mass="kg",Length="m",Inertia="kg*m^2",Angle="rad"},p.AssemblyPath,p.Configuration,p.CapturedUtc,MeshSettings=p.Export,Alignment=p.Alignment,p.ChildFramesFollowRoot,RootFrameInCad=Math3.LinkFrame(p,p.Links.Single(x=>x.Id==p.RootLink)),CapturedRootFrameInCad=p.Links.Single(x=>x.Id==p.RootLink).ZeroFrame,TotalMassKg=p.Links.Sum(l=>OriginWorkflow.Properties(p,l).Mass),Links=p.Links.Select(l=>new{l.Name,l.Components,FrameInCad=Math3.LinkFrame(p,l),l.Origin,Properties=OriginWorkflow.Properties(p,l)}).ToArray(),Components=p.Components.Select(c=>new{c.Name,c.Path,c.Configuration,c.Excluded,c.Hidden,c.MaterialAcknowledged,c.ZeroTransform,Cad=c.Cad,Override=c.Override,Effective=c.Excluded?null:Math3.Effective(c)}).ToArray(),Diagnostics=errors};
                File.WriteAllText(Path.Combine(stage,"validation-report.json"),ProjectIO.Json(report),new UTF8Encoding(false));File.WriteAllText(Path.Combine(stage,".cad-urdf-maker-output"),"CAD-URDF Maker schema 1\n");
                var xml=new XmlDocument();xml.Load(Path.Combine(stage,urdfFile));foreach(var l in p.Links)MeshIO.ReadStl(Path.Combine(stage,"meshes",l.Name+".stl"));
                if(Directory.Exists(full))Directory.Move(full,backup);try{Directory.Move(stage,full);}catch{if(Directory.Exists(backup))Directory.Move(backup,full);throw;}
                // Keep the previous successful export as a recoverable sibling folder.
            }finally{if(Directory.Exists(stage))Directory.Delete(stage,true);}
        }
    }
}
